$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$mp=Join-Path $root 'port-changes.json';$m=Get-Content $mp -Raw|ConvertFrom-Json
$targets=@(
 [pscustomobject]@{rel='content/trains/station/GlobalStation.java';changes=@([pscustomobject]@{from='NbtUtils.readBlockPos(c.getCompound("Pos"))';to='NbtUtils.readBlockPos(c, "Pos").orElseThrow()'});status='Native Fabric GlobalStation mail persistence adapted to Minecraft 1.21.1 NBT helpers.'},
 [pscustomobject]@{rel='content/trains/station/StationBlockEntity.java';changes=@([pscustomobject]@{from='IWrenchable.playRotateSound(level, bogeyPos);';to='bogey.playRotateSound(level, bogeyPos);'});status='Native station bogey resizing retained through the baseline instance wrench sound API.'},
 [pscustomobject]@{rel='compat/computercraft/implementation/peripherals/NixieTubePeripheral.java';changes=@([pscustomobject]@{from='Component.Serializer.toJson(Component.literal(arguments.getString(0)))';to='Component.Serializer.toJson(Component.literal(arguments.getString(0)), world.registryAccess())'});status='Native Nixie ComputerCraft text control adapted to registry-aware component serialization.'},
 [pscustomobject]@{rel='compat/computercraft/implementation/luaObjects/PackageLuaObject.java';changes=@([pscustomobject]@{from='PackageItem.hasFragmentData(box)';to='PackageItem.hasOrderData(box)'});status='Native package ComputerCraft order-data check aligned with Create 6 package component API.'},
 [pscustomobject]@{rel='compat/computercraft/implementation/ComputerBehaviour.java';changes=@([pscustomobject]@{from='cmbe.generatedSpeed';to='cmbe.getGeneratedSpeed()'});status='Native Creative Motor peripheral adapted to the public baseline speed accessor.'},
 [pscustomobject]@{rel='content/logistics/stockTicker/StockTickerBlockEntity.java';changes=@([pscustomobject]@{from='receivedPayments.nonEmptyViews().forEach(summary::add);';to="receivedPayments.nonEmptyViews().forEach(view ->`n`t`t`tsummary.add(view.getResource().toStack(), TransferUtil.truncateLong(view.getAmount())));"});status='Native Stock Ticker payment tooltip adapted from Fabric storage views to inventory summary stacks.'}
)
foreach($t in $targets){$p=Join-Path $root "source/fabric/src/main/java/com/simibubi/create/$($t.rel)";$x=[IO.File]::ReadAllText($p);foreach($c in $t.changes){if(-not$x.Contains($c.from)){throw "Data/inventory tail anchor missing in $($t.rel): $($c.from)"};$x=$x.Replace($c.from,$c.to)};[IO.File]::WriteAllText($p,$x,[Text.UTF8Encoding]::new($false));$e=$m.files|Where-Object path -eq $t.rel;$e.changes=@($e.changes)+$t.changes;if($e.PSObject.Properties.Name -contains 'status'){$e.status=$t.status}else{$e|Add-Member -NotePropertyName status -NotePropertyValue $t.status}}
$m|ConvertTo-Json -Depth 20|Set-Content $mp -Encoding utf8;Write-Output 'Cleaned native component, inventory, and station API tail.'
